DELETE FROM games WHERE igdb_id >= 900000;
-- fake games: pin a huge data version so the background refresh never swaps in
-- real IGDB data for these ids, and fill fields added after v1
UPDATE games SET data = json_set(data, '$._v', 999, '$.heroImageId', json('null'), '$.themes', json('[]'), '$.trailerYoutubeId', json('null'), '$.freeToPlay', json('false')) WHERE igdb_id >= 900000;
